        ["Hi."] = "Hola.",
        ["Would you like to buy a beer?"] = "¿Te gustaría comprar una cerveza?",
        ["How much do they cost?"] = "¿Cuánto cuestan?",
        ["Just 2 gold pieces."] = "Sólo 2 piezas de oro.",
        ["Select an Option"] = "Selecciona una opción",
        ["Yes please!"] = "¡Sí, por favor!",
        ["Coming right up [sir/ma'am]!"] = "¡Ya viene [sir/ma'am]!",
